/* 00-fonts.css — 内嵌字体（base64，自动生成区，别手改） */
/* ============================================================
   战术体字体
   ============================================================ */
@font-face {
  font-family: 'TacticalBold';
  src: url('data:font/ttf;base64,') format('truetype');
  font-weight: normal;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: 'TacticalMedium';
  src: url('data:font/ttf;base64,') format('truetype');
  font-weight: normal;
  font-style: normal;
  font-display: swap;
}
